/// The text of an English label the example writes, in the language the app shows (English when it is not held).
String cylExampleText(String english) {
  final key = _keysByEnglish[english];
  if (key == null) return english;
  final language = CYLSearchDiscoverData.languageFolder(PlatformDispatcher.instance.locale);
  return _texts[language]?[key] ?? _texts['en']?[key] ?? english;
}
